mapper.sql:
WITH visible_houses AS (
    SELECT id, created_business_date
    FROM house
    WHERE created_at <= #{asOfUtc}
), ranked_history AS (
    SELECT sh.house_id, sh.to_stage,
           ROW_NUMBER() OVER (
               PARTITION BY sh.house_id ORDER BY sh.changed_at DESC, sh.id DESC
           ) AS rn
    FROM stage_history sh
    JOIN visible_houses h ON h.id = sh.house_id
    WHERE sh.changed_at <= #{asOfUtc}
), last_photos AS (
    SELECT p.house_id, MAX(p.business_date) AS last_photo_business_date
    FROM photo p
    JOIN visible_houses h ON h.id = p.house_id
    WHERE p.uploaded_at <= #{asOfUtc}
      AND p.business_date <= #{asOfBusinessDate}
    GROUP BY p.house_id
), house_snapshot AS (
    SELECT h.id,
           COALESCE(r.to_stage, 'LAND_CLEARING') AS stage,
           COALESCE(p.last_photo_business_date, h.created_business_date) AS last_activity_date
    FROM visible_houses h
    LEFT JOIN ranked_history r ON r.house_id = h.id AND r.rn = 1
    LEFT JOIN last_photos p ON p.house_id = h.id
)
